import{_ as i,a0 as l,w as p,s as r,I as s,x as t,a1 as o,A as e,ao as d}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const C=JSON.parse('{"title":"理解 Linux 中的 Shutdown、Poweroff、Halt 和 Reboot 命令 | LCTT x X-CMD","titleTemplate":false,"description":"理解 Linux 中的 Shutdown、Poweroff、Halt 和 Reboot 命令 | LCTT (201706) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"理解 Linux 中的 Shutdown、Poweroff、Halt 和 Reboot 命令 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"理解 Linux 中的 Shutdown、Poweroff、Halt 和 Reboot 命令 | LCTT (201706) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201706/20170512 Understanding Shutdown, Poweroff Halt and Reboot Commands in Linux","title":"理解 Linux 中的 Shutdown、Poweroff、Halt 和 Reboot 命令","tag":"201706","desc":""},"relativePath":"201706/20170512 Understanding Shutdown, Poweroff Halt and Reboot Commands in Linux.md","filePath":"[post].md"}'),h={name:"201706/20170512 Understanding Shutdown, Poweroff Halt and Reboot Commands in Linux.md"};function u(f,n,b,g,w,m){const a=l("Link");return p(),r("div",null,[n[16]||(n[16]=s("h1",{id:"理解-linux-中的-shutdown、poweroff、halt-和-reboot-命令",tabindex:"-1"},[t("理解 Linux 中的 Shutdown、Poweroff、Halt 和 Reboot 命令 "),s("a",{class:"header-anchor",href:"#理解-linux-中的-shutdown、poweroff、halt-和-reboot-命令","aria-label":"Permalink to “理解 Linux 中的 Shutdown、Poweroff、Halt 和 Reboot 命令”"},"​")],-1)),n[17]||(n[17]=s("p",null,[t("在本篇中，我們會向你解釋 "),s("strong",null,"shutdown、poweroff、halt 以及 reboot"),t(" 命令。我們會解釋當使用可選項時，它們實際做了什麼。")],-1)),s("p",null,[n[1]||(n[1]=t("如果你想深入管理 Linux 服務器，那麼為了有效和可靠的服務器管理，這些",-1)),o(a,{href:"https://www.tecmint.com/60-commands-of-linux-a-guide-from-newbies-to-system-administrator/"},{default:e(()=>[...n[0]||(n[0]=[t("重要的 Linux 命令",-1)])]),_:1}),n[2]||(n[2]=t("你需要完全理解。",-1))]),n[18]||(n[18]=d(`<p>通常上，當你想要關閉或者重啓你的機器時，你會運行下面之一的命令：</p><h3 id="shutdown-命令" tabindex="-1">Shutdown 命令 <a class="header-anchor" href="#shutdown-命令" aria-label="Permalink to “Shutdown 命令”">​</a></h3><p><strong>shutdown</strong> 會給系統計劃一個時間關機。它可被用於停止、關機、重啓機器。</p><p>你也許會指定一個時間字符串（通常是 “now” 或者 “hh:mm” 用於小時/分鐘）作為第一個參數。額外地，你也可以設置一個廣播信息在系統關閉前發送給所有已登錄的用户。</p><p>重要：如果使用了時間參數，系統關機前 5 分鐘，/run/nologin 文件會被創建來確保沒有人可以再登錄。</p><p>shutdown 命令示例：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># shutdown</span></span>
<span class="line"><span># shutdown now</span></span>
<span class="line"><span># shutdown 13:20  </span></span>
<span class="line"><span># shutdown -p now	#關閉機器</span></span>
<span class="line"><span># shutdown -H now	#停止機器		</span></span>
<span class="line"><span># shutdown -r09:35	#在 09:35am 重啓機器</span></span></code></pre></div><p>要取消即將的關機，只要輸入下面的命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># shutdown -c</span></span></code></pre></div><h3 id="halt-命令" tabindex="-1">Halt 命令 <a class="header-anchor" href="#halt-命令" aria-label="Permalink to “Halt 命令”">​</a></h3><p><strong>halt</strong> 通知硬件來停止所有的 CPU 功能，但是仍然保持通電。你可以用它使系統處於低層維護狀態。</p><p>注意在有些情況會它會完全關閉系統。下面是 halt 命令示例：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># halt		   #停止機器</span></span>
<span class="line"><span># halt -p	   #關閉機器</span></span>
<span class="line"><span># halt --reboot    #重啓機器</span></span></code></pre></div><h3 id="poweroff-命令" tabindex="-1">poweroff 命令 <a class="header-anchor" href="#poweroff-命令" aria-label="Permalink to “poweroff 命令”">​</a></h3><p><strong>poweroff</strong> 會發送一個 ACPI 信號來通知系統關機。</p><p>下面是 poweroff 命令示例：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># poweroff   	       #關閉機器</span></span>
<span class="line"><span># poweroff --halt      #停止機器</span></span>
<span class="line"><span># poweroff --reboot    #重啓機器</span></span></code></pre></div><h3 id="reboot-命令" tabindex="-1">Reboot 命令 <a class="header-anchor" href="#reboot-命令" aria-label="Permalink to “Reboot 命令”">​</a></h3><p>reboot 通知系統重啓。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># reboot            #重啓機器</span></span>
<span class="line"><span># reboot --halt     #停止機器</span></span>
<span class="line"><span># reboot -p   	    #關閉機器</span></span></code></pre></div><p>就是這樣了！如先前提到的，理解這些命令能夠有效並可靠地在多用户環境下管理 Linux 服務器。你有一些額外的想法麼？在評論區留言與我們分享。</p><hr><p>作者簡介：</p><p>Aaron Kili 是一名 Linux 和 F.O.S.S 的愛好者，未來的 Linux 系統管理員、網站開發人員，目前是 TecMint 的內容創作者，他喜歡用電腦工作，並樂於分享知識。</p><hr>`,25)),s("p",null,[n[4]||(n[4]=t("via: ",-1)),o(a,{href:"https://www.tecmint.com/shutdown-poweroff-halt-and-reboot-commands-in-linux/"},{default:e(()=>[...n[3]||(n[3]=[t("https://www.tecmint.com/shutdown-poweroff-halt-and-reboot-commands-in-linux/",-1)])]),_:1})]),s("p",null,[n[8]||(n[8]=t("作者：",-1)),o(a,{href:"https://www.tecmint.com/author/aaronkili/"},{default:e(()=>[...n[5]||(n[5]=[t("Aaron Kili ",-1)])]),_:1}),n[9]||(n[9]=t(" 譯者：",-1)),o(a,{href:"https://github.com/geekpi"},{default:e(()=>[...n[6]||(n[6]=[t("geekpi",-1)])]),_:1}),n[10]||(n[10]=t(" 校對：",-1)),o(a,{href:"https://github.com/jasminepeng"},{default:e(()=>[...n[7]||(n[7]=[t("jasminepeng",-1)])]),_:1})]),s("p",null,[n[13]||(n[13]=t("本文由 ",-1)),o(a,{href:"https://github.com/LCTT/TranslateProject"},{default:e(()=>[...n[11]||(n[11]=[t("LCTT",-1)])]),_:1}),n[14]||(n[14]=t(" 原創編譯，",-1)),o(a,{href:"https://linux.cn/"},{default:e(()=>[...n[12]||(n[12]=[t("Linux中國",-1)])]),_:1}),n[15]||(n[15]=t(" 榮譽推出",-1))])])}const c=i(h,[["render",u]]);export{C as __pageData,c as default};
